//! Replays `testdata/port/ingest/watcher.json`, generated by the real Go
//! `TestPortIngestWatcherContract`: debounce, stability check, forced enqueue,
//! processing/failed directories with the error sidecar, duplicates, ignore
//! rules and the initial recursive scan. Deterministic scenarios use a fake
//! clock; "live" scenarios run the real notify loop and only compare the
//! eventual jobs, documents and file trees.
#![cfg(unix)]

use base64::Engine as _;
use regex::Regex;
use rusqlite::types::ValueRef;
use serde_json::{Value, json};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use symdesk_ingest::Store;
use symdesk_ingest::watcher::{Ctx, FakeClock, Watcher, WatcherOptions};

fn fixture() -> Value {
    let f: Value = serde_json::from_slice(
        &std::fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/port/ingest/watcher.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(f["schema_version"], 1);
    f
}

fn mkdir_700(path: &Path) {
    use std::os::unix::fs::DirBuilderExt;
    std::fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(path)
        .unwrap();
}

fn write_600(path: &Path, content: &[u8]) {
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;
    let mut f = std::fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .mode(0o600)
        .open(path)
        .unwrap();
    f.write_all(content).unwrap();
}

fn dump_table(
    db: &rusqlite::Connection,
    table: &str,
    ts: &Regex,
    norm: &dyn Fn(&str) -> String,
) -> Vec<Value> {
    let mut stmt = db
        .prepare(&format!("SELECT * FROM {table} ORDER BY rowid"))
        .unwrap();
    let cols: Vec<String> = stmt
        .column_names()
        .iter()
        .map(|c| (*c).to_owned())
        .collect();
    let mut rows = stmt.query([]).unwrap();
    let mut out = Vec::new();
    while let Some(row) = rows.next().unwrap() {
        let mut map = serde_json::Map::new();
        for (i, c) in cols.iter().enumerate() {
            let mut v = match row.get_ref(i).unwrap() {
                ValueRef::Null => Value::Null,
                ValueRef::Integer(n) => json!(n),
                ValueRef::Real(f) => json!(f),
                ValueRef::Text(t) => {
                    json!(ts.replace_all(&norm(&String::from_utf8_lossy(t)), "<TS>"))
                }
                ValueRef::Blob(b) => json!(norm(&String::from_utf8_lossy(b))),
            };
            if c.ends_with("_at") && v.as_str().is_some_and(|s| !s.is_empty()) {
                v = json!("<TS>");
            }
            map.insert(c.clone(), v);
        }
        out.push(Value::Object(map));
    }
    out
}

fn snapshot_tree(root: &Path, norm: &dyn Fn(&str) -> String, sidecar_ts: &Regex) -> Vec<Value> {
    use std::os::unix::fs::PermissionsExt;
    fn walk(
        path: &Path,
        root: &Path,
        out: &mut Vec<Value>,
        norm: &dyn Fn(&str) -> String,
        ts: &Regex,
    ) {
        let meta = std::fs::symlink_metadata(path).unwrap();
        let r = path
            .strip_prefix(root)
            .unwrap()
            .to_string_lossy()
            .into_owned();
        let mode = format!("{:04o}", meta.permissions().mode() & 0o777);
        if meta.file_type().is_symlink() {
            let target = std::fs::read_link(path)
                .unwrap()
                .to_string_lossy()
                .into_owned();
            out.push(json!({"path": r, "type": "symlink", "mode": "0777", "text": target}));
        } else if meta.is_dir() {
            out.push(json!({"path": r, "type": "dir", "mode": mode}));
            let mut kids: Vec<_> = std::fs::read_dir(path)
                .unwrap()
                .map(|e| e.unwrap().path())
                .collect();
            kids.sort();
            for k in kids {
                walk(&k, root, out, norm, ts);
            }
        } else {
            let mut data = std::fs::read(path).unwrap();
            if r.ends_with(".error.json") {
                let text = norm(&String::from_utf8_lossy(&data));
                data = ts
                    .replace_all(&text, r#""failed_at": "<TS>""#)
                    .into_owned()
                    .into_bytes();
            }
            let mut e = json!({"path": r, "type": "file", "mode": mode});
            let b64 = base64::engine::general_purpose::STANDARD.encode(&data);
            if !b64.is_empty() {
                e["b64"] = json!(b64);
            }
            out.push(e);
        }
    }
    let mut out = Vec::new();
    walk(root, root, &mut out, norm, sidecar_ts);
    out.retain(|e| {
        let p = e["path"].as_str().unwrap();
        !(p.is_empty() || p.starts_with("db"))
    });
    out.sort_by(|a, b| a["path"].as_str().cmp(&b["path"].as_str()));
    out
}

fn count_jobs(db_path: &Path) -> i64 {
    let db =
        rusqlite::Connection::open_with_flags(db_path, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)
            .unwrap();
    db.query_row("SELECT COUNT(*) FROM jobs", [], |r| r.get(0))
        .unwrap_or(0)
}

fn observe(sc: &Value, scratch: &Path) -> Value {
    let id = sc["id"].as_str().unwrap();
    let root = scratch.join(id);
    let _ = std::fs::remove_dir_all(&root);
    mkdir_700(&root.join("inbox"));
    let root = std::fs::canonicalize(&root).unwrap();
    let live = sc["live"].as_bool().unwrap_or(false);
    let store = Arc::new(Mutex::new(Store::open(&root.join("db/docs.db")).unwrap()));
    let abs = |rel: &str| root.join(rel).to_string_lossy().into_owned();
    let opt = |k: &str| {
        sc["opts"][k]
            .as_str()
            .filter(|s| !s.is_empty())
            .map(&abs)
            .unwrap_or_default()
    };
    let clock = (!live).then(|| Arc::new(FakeClock::new()));
    let w = Watcher::with_options(
        Arc::clone(&store),
        &abs("inbox"),
        WatcherOptions {
            stable_for: Duration::from_millis(sc["opts"]["stable_for_ms"].as_u64().unwrap_or(0)),
            processing_dir: opt("processing"),
            processed_dir: opt("processed"),
            failed_dir: opt("failed"),
            clock: clock
                .clone()
                .map(|c| c as Arc<dyn symdesk_ingest::watcher::Clock>),
        },
    )
    .unwrap();
    let logs: Arc<Mutex<String>> = Arc::new(Mutex::new(String::new()));
    {
        let logs = Arc::clone(&logs);
        w.set_log(Arc::new(move |m| {
            let mut l = logs.lock().unwrap();
            l.push_str(&m);
            l.push('\n');
        }));
    }
    let ctx = Ctx::new();
    let root_str = root.to_string_lossy().into_owned();
    let norm = {
        let root_str = root_str.clone();
        move |s: &str| s.replace(&root_str, "<ROOT>")
    };
    let sidecar_ts = Regex::new(r#""failed_at": "[^"]*""#).unwrap();
    let db_path = root.join("db/docs.db");
    let mut results = Vec::new();
    let mut started = false;
    for step in sc["steps"].as_array().unwrap() {
        let path = step["path"].as_str().unwrap_or("");
        let mut res = String::new();
        match step["op"].as_str().unwrap() {
            "write" => {
                let p = root.join(path);
                mkdir_700(p.parent().unwrap());
                write_600(&p, step["content"].as_str().unwrap_or("").as_bytes());
            }
            "append" => {
                use std::io::Write;
                let mut f = std::fs::OpenOptions::new()
                    .append(true)
                    .open(root.join(path))
                    .unwrap();
                f.write_all(step["content"].as_str().unwrap_or("").as_bytes())
                    .unwrap();
            }
            "mkdir" => mkdir_700(&root.join(path)),
            "remove" => {
                let p = root.join(path);
                if p.is_dir() {
                    std::fs::remove_dir_all(&p).unwrap();
                } else if std::fs::symlink_metadata(&p).is_ok() {
                    std::fs::remove_file(&p).unwrap();
                }
            }
            "rename" => {
                std::fs::rename(root.join(path), root.join(step["to"].as_str().unwrap())).unwrap()
            }
            "symlink" => {
                std::os::unix::fs::symlink(step["to"].as_str().unwrap(), root.join(path)).unwrap()
            }
            "set-mtime" => {
                let t = std::time::UNIX_EPOCH + Duration::from_secs(step["secs"].as_u64().unwrap());
                std::fs::OpenOptions::new()
                    .write(true)
                    .open(root.join(path))
                    .unwrap()
                    .set_modified(t)
                    .unwrap();
            }
            "debounce" => w.debounce_file(&ctx, &abs(path)),
            "cancel" => w.cancel_debounce(&abs(path)),
            "advance" => clock
                .as_ref()
                .unwrap()
                .advance(Duration::from_millis(step["ms"].as_u64().unwrap())),
            "enqueue" => {
                if let Err(e) = w.enqueue_file(&abs(path)) {
                    res = norm(&e);
                }
            }
            "start" => match {
                // FSEvents can still deliver the creation of the scenario's own setup
                // directories to a stream opened right after; let those events drain first.
                std::thread::sleep(Duration::from_millis(1000));
                w.start(&ctx)
            } {
                Ok(()) => {
                    started = true;
                    if sc["live"] == true {
                        // The OS watch registers asynchronously; give it time before the
                        // first filesystem event of a live scenario (saturated hosts lost it).
                        std::thread::sleep(Duration::from_millis(1500));
                    }
                }
                Err(e) => res = norm(&e),
            },
            "pending" => {
                let mut keys: Vec<String> = w
                    .pending_snapshot()
                    .into_iter()
                    .map(|(k, size)| {
                        if std::fs::symlink_metadata(&k).is_ok_and(|m| m.is_dir()) {
                            format!("{} dir", norm(&k))
                        } else {
                            format!("{} size={size}", norm(&k))
                        }
                    })
                    .collect();
                keys.sort();
                res = keys.join("; ");
            }
            "wait-jobs" => {
                let want = step["n"].as_i64().unwrap();
                let deadline = Instant::now() + Duration::from_secs(120);
                while Instant::now() < deadline && count_jobs(&db_path) < want {
                    std::thread::sleep(Duration::from_millis(25));
                }
                assert!(
                    count_jobs(&db_path) >= want,
                    "{id}: timed out waiting for {want} jobs"
                );
            }
            "pause" => std::thread::sleep(Duration::from_millis(step["ms"].as_u64().unwrap())),
            other => panic!("unknown step {other}"),
        }
        results.push(json!(res));
    }
    if started {
        ctx.cancel();
        let deadline = Instant::now() + Duration::from_secs(10);
        while Instant::now() < deadline
            && !logs.lock().unwrap().contains("Shutting down event loop...")
        {
            std::thread::sleep(Duration::from_millis(10));
        }
    }
    w.close();
    drop(w);
    drop(store);

    let ts = Regex::new(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|[+-]\d\d:\d\d)").unwrap();
    let db =
        rusqlite::Connection::open_with_flags(&db_path, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)
            .unwrap();
    let mut tables = serde_json::Map::new();
    for t in ["documents", "jobs"] {
        tables.insert(t.to_owned(), Value::Array(dump_table(&db, t, &ts, &norm)));
    }
    let mut out = json!({
        "results": results,
        "files": snapshot_tree(&root, &norm, &sidecar_ts),
        "tables": tables,
    });
    if !live {
        let text = logs.lock().unwrap().clone();
        let lines: Vec<String> = text
            .trim_end_matches('\n')
            .split('\n')
            .filter(|l| !l.is_empty())
            .map(&norm)
            .collect();
        // Go marshals a nil slice with `omitempty`: no key at all.
        if !lines.is_empty() {
            out["logs"] = json!(lines);
        }
    }
    out
}

fn diff(path: &str, want: &Value, got: &Value, out: &mut Vec<String>) {
    match (want, got) {
        (Value::Object(a), Value::Object(b)) => {
            for key in a
                .keys()
                .chain(b.keys())
                .collect::<std::collections::BTreeSet<_>>()
            {
                diff(
                    &format!("{path}.{key}"),
                    a.get(key).unwrap_or(&Value::Null),
                    b.get(key).unwrap_or(&Value::Null),
                    out,
                );
            }
        }
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => {
            for (i, (x, y)) in a.iter().zip(b).enumerate() {
                diff(&format!("{path}[{i}]"), x, y, out);
            }
        }
        _ => {
            if want != got {
                let clip = |v: &Value| {
                    let s = v.to_string();
                    if s.len() > 300 {
                        format!("{}…", &s[..300])
                    } else {
                        s
                    }
                };
                out.push(format!("{path}: go {} rust {}", clip(want), clip(got)));
            }
        }
    }
}

fn compare(case: &Value, scratch: &Path) -> Vec<String> {
    let got = observe(&case["scenario"], scratch);
    let mut want = serde_json::Map::new();
    for key in ["results", "files", "tables", "logs"] {
        if let Some(v) = case.get(key) {
            want.insert(key.to_owned(), v.clone());
        }
    }
    let mut diffs = Vec::new();
    diff("", &Value::Object(want), &got, &mut diffs);
    diffs
}

fn scratch(name: &str) -> std::path::PathBuf {
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("{name}-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// Live scenarios depend on OS file-event delivery, which a saturated host delays or merges. A
/// live scenario is therefore replayed up to three times and passes when any attempt matches the
/// Go recording exactly; a deterministic divergence fails every attempt. Fake-clock scenarios run
/// once.
fn compare_with_retry(case: &Value, dir: &Path) -> Vec<String> {
    let attempts = if case["scenario"]["live"] == true {
        3
    } else {
        1
    };
    let mut last = Vec::new();
    for attempt in 1..=attempts {
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| compare(case, dir)));
        match outcome {
            Ok(diffs) if diffs.is_empty() => return diffs,
            Ok(diffs) => last = diffs,
            Err(panic) if attempt == attempts => std::panic::resume_unwind(panic),
            Err(_) => last = vec!["attempt panicked".to_owned()],
        }
    }
    last
}

#[test]
fn watcher_matches_go() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    assert!(cases.len() >= 30, "scenarios shrank: {}", cases.len());
    let dir = scratch("watcher");
    let mut failures = Vec::new();
    for case in cases {
        let id = case["scenario"]["id"].as_str().unwrap();
        for d in compare_with_retry(case, &dir).into_iter().take(6) {
            failures.push(format!("{id}: {d}"));
        }
    }
    let _ = std::fs::remove_dir_all(&dir);
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn watcher_negative_controls_are_caught() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    let dir = scratch("watcher-neg");
    let case = cases
        .iter()
        .find(|c| c["scenario"]["id"] == "undetectable-file-goes-to-failed-with-sidecar")
        .unwrap();
    assert!(compare(case, &dir).is_empty());
    for mutate in [
        |c: &mut Value| c["files"][0]["mode"] = json!("0755"),
        |c: &mut Value| c["logs"][0] = json!("[Watcher] other"),
        |c: &mut Value| c["tables"]["jobs"] = json!([{"id": 1}]),
        |c: &mut Value| c["results"][0] = json!("unexpected"),
    ] {
        let mut tampered = case.clone();
        mutate(&mut tampered);
        assert!(
            !compare(&tampered, &dir).is_empty(),
            "tampering went unnoticed"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
}
